/// Task 1: input is assumed non-empty.
pub fn find_max_precedence_type(types: Vec<DType>) -> DType {
    // Panics on empty input, which is acceptable under the stated assumption.
    types
        .into_iter()
        .max_by_key(|t| t.precedence())
        .expect("types must be non-empty")
}

/// Task 2: at least one of the collections is assumed non-empty.
pub fn find_common_type(array_types: Vec<DType>, scalar_types: Vec<DType>) -> Option<DType> {
    match (array_types.is_empty(), scalar_types.is_empty()) {
        (true, true) => None, // outside assumption, but keeps function total
        (false, true) => Some(find_max_precedence_type(array_types)),
        (true, false) => Some(find_max_precedence_type(scalar_types)),
        (false, false) => {
            let arr_max = find_max_precedence_type(array_types);
            let scl_max = find_max_precedence_type(scalar_types);

            if arr_max.kind() == scl_max.kind() {
                Some(arr_max)
            } else {
                Some(scl_max)
            }
        }
    }
}